        else:
            skill_count[skills[end]] = 1

        while len(skill_count) > max_unique_skills:
            max_unique_skills = len(skill_count)
            max_length = end - start + 1

        if len(skill_count) == max_unique_skills:
            max_length = max(max_length, end - start + 1)

